  "뷰어 선택·모드·OHIF 등": "Sélection du visualiseur, modes, OHIF, etc.",
  "공통 설정": "Paramètres communs",
  "입니다. 표시·아이콘·사용 패턴은 좌측 [뷰어 — TY Viewer]/[뷰어 — In Viewer] 탭에서 뷰어별로 설정하며, 기능은 두 뷰어 동일합니다.": ". L'affichage, les icônes et les habitudes d'utilisation se règlent par visualiseur dans les onglets [Visualiseur — TY Viewer]/[Visualiseur — In Viewer] ; les fonctions sont identiques dans les deux.",
  "영상 파이프라인": "Chaîne de traitement des images",
  "WASM 디코딩 파이프라인 (베타) — 원본 픽셀(WADO-RS bulkdata)을 브라우저에서 직접 디코딩": "Chaîne de décodage WASM (bêta) — décodage des pixels d'origine (bulkdata WADO-RS) directement dans le navigateur",
  "켜면 2D 뷰어가 서버 렌더링(JPEG) 대신 원본 16bit 프레임을 받아 WASM 코덱으로 디코딩합니다. W/L 조정이 서버 왕복 없이 즉시 반영되고, 병원 설정의 전송구문(JPEG2000/JPEG-LS)으로 수신합니다. 디코딩 전에는 서버 렌더링으로 표시(자동 폴백).": "Activé, le visualiseur 2D reçoit les images d'origine 16 bits au lieu du rendu serveur (JPEG) et les décode avec un codec WASM. Les réglages W/L s'appliquent immédiatement sans aller-retour serveur, et la réception utilise la syntaxe de transfert configurée pour l'établissement (JPEG2000/JPEG-LS). Avant décodage, l'affichage utilise le rendu serveur (repli automatique).",
  "제품 모드 프로파일 (05 Mode Profile — 서버 JSON)": "Profil de mode produit (05 Mode Profile — JSON serveur)",
  "모드 선택…": "Choisir un mode…",
  "현재 적용": "Actuellement appliqué",
  "모드 적용 — 왼쪽 ⟳ Refresh로 즉시 확인": "Appliquer le mode — vérification immédiate via ⟳ Refresh à gauche",
  "현재 워크리스트·뷰어 레이아웃(컬럼·검색필드·팔레트/썸네일 배치·선택 뷰어)을 선택한 프로파일에 저장 (전역)": "Enregistrer la disposition actuelle de la worklist et du visualiseur (colonnes, champs de recherche, position de la palette/des vignettes, visualiseur sélectionné) dans le profil choisi (global)",
  "저장할 프로파일을 먼저 선택하세요": "Sélectionnez d'abord le profil à enregistrer",
  "현재 화면 구성을": "Enregistrer la configuration actuelle de l'écran dans le profil",
  "프로파일에 저장할까요? (전역 — 모든 사용자에게 적용)": " ? (global — s'applique à tous les utilisateurs)",
  "프로파일에 저장했습니다 (전역)": "Enregistré dans le profil (global)",
  "현재 화면을 프로파일에 저장": "Enregistrer l'écran actuel dans le profil",
  "Core 기능은 동일, 화면 구성(컬럼·검색필드·팔레트/썸네일 배치·더블클릭·선택 뷰어)만 제품별 프로파일로 전환 — 타 PACS 사용 경험 그대로 이전. 프로파일 정의는 서버 전역 설정(mode.profiles)에서 로드.": "Les fonctions de base restent identiques ; seule la configuration de l'écran (colonnes, champs de recherche, position de la palette/des vignettes, double-clic, visualiseur sélectionné) change selon le profil produit — pour retrouver l'ergonomie d'un autre PACS. Les définitions de profil sont chargées depuis la configuration globale du serveur (mode.profiles).",
  "=INFINITT 스타일 레이아웃 저장소 ·": "= dépôt de dispositions de style INFINITT ·",
  "=자체 뷰어 레이아웃.": "= disposition du visualiseur intégré.",
  "프로파일 JSON 편집 (관리자 — 전역 적용)": "Édition du JSON de profil (administrateur — application globale)",
