  "Live 모드에도 함께": "mode Live",
  "적용됩니다. 수동일 때 원격에 변경이 생기면 목록을 바꾸지 않고 상단에 알림만 띄웁니다.": ". En mode manuel, une modification distante n'actualise pas la liste : seule une notification apparaît en haut.",
  "초는 매우 짧습니다 — Live 모드에서는 원격 PACS 에 그만큼 자주 질의합니다.": "s est très court — en mode Live, le PACS distant est interrogé à cette fréquence.",
  "워크리스트: Enter=View&Draft · B=일괄검토 · E=Emergency │ 뷰어: ←→ 이미지 · I 반전 · R 회전 · F Fit · L Link · 1/2/4 분할 · Space Cine · Esc 닫기": "Worklist : Entrée = View&Draft · B = révision en lot · E = Emergency │ Visualiseur : ←→ images · I inversion · R rotation · F Fit · L Link · 1/2/4 disposition · Espace ciné · Échap fermer",
