  "최근 환자 순": "par patients les plus récents",
  "으로 훑어 시리즈 썸네일 → 각 시리즈의 이미지 순서로 미리 받아 둡니다. 저장 위치는 브라우저 전용 영역이라": " en pré-chargeant les vignettes de séries puis les images de chaque série. Le stockage se fait dans une zone réservée au navigateur :",
  "탐색기에 보이지 않고 권한 프롬프트도 없습니다": "il n'apparaît pas dans l'explorateur et aucune demande d'autorisation n'est affichée",
  ". 받아 둔 검사는 서버 왕복 없이 열립니다.": ". Les examens pré-chargés s'ouvrent sans aller-retour serveur.",
  "⚠ 현재는": "⚠ Actuellement,",
  "Live 모드 + 2D 뷰어(SaintView·T-View·I-View)": "mode Live + visualiseurs 2D (SaintView, T-View, I-View)",
  "에서만 동작합니다. W/L 을 조정하는 동안에는 서버 렌더로 자동 폴백합니다(저장본은 검사 기본 W/L 로 구운 영상이라 그대로 쓰면 표시 W/L 과 실제 영상이 어긋납니다).": " uniquement. Pendant un réglage du W/L, le rendu serveur est utilisé automatiquement (les images stockées sont figées avec le W/L par défaut de l'examen : les réutiliser telles quelles ferait diverger le W/L affiché et l'image réelle).",
  "로그아웃·세션 만료 시 받아 둔 영상은 전부 삭제됩니다": "À la déconnexion ou à l'expiration de la session, toutes les images pré-chargées sont supprimées",
