  "더 받지 않습니다": "plus rien n'est téléchargé",
  ". 계속 받다가 브라우저 할당량이 차면 브라우저가 받아 둔 영상을": ". Si le téléchargement se poursuivait jusqu'à saturer le quota du navigateur, celui-ci supprimerait les images stockées",
