  "그 검사를 워크리스트에서 열면 그때 다시 받습니다(상한·삭제 기준을 바꾸거나 [지금 비우기] 를 눌러도 초기화됩니다).": "Il sera de nouveau téléchargé lors de son ouverture depuis la worklist (la modification de la limite ou du critère de suppression, ainsi que [Vider maintenant], réinitialisent également cet état).",
  "상한 근접 알림": "Alerte d'approche de la limite",
  "사용량이": "Alerte lorsque l'utilisation dépasse",
  "% 를 넘으면 알립니다 —": " % —",
  "다운로드가 곧 중지될 때만": "uniquement lorsque le téléchargement est sur le point de s'interrompre",
  "뜹니다(자동 삭제가 꺼져 있거나, 열려 있는 검사만으로 상한을 넘어 지울 것이 없을 때). 자동 삭제가 정상 작동 중이면 사용량이 상한에 붙어 있는 것이 정상이라 알리지 않습니다. 워크리스트 창에서 1회 — 판독 중인 뷰어 창에는 띄우지 않습니다.": " (suppression automatique désactivée, ou limite dépassée par les seuls examens ouverts, sans rien à supprimer). Si la suppression automatique fonctionne, une utilisation proche de la limite est normale et aucune alerte n'est affichée. Une seule fois dans la fenêtre worklist — jamais dans une fenêtre de visualisation en cours de lecture.",
