  ". MG 에서 계측을 쓰신다면 이 체크를 켜서 Series Layout 으로 두세요(뷰 하나당 페인 하나 — W/L·확대·계측이 뷰마다 따로 동작합니다). I-View 는 타일에도 계측이 나오므로 영향이 없습니다.": ". Si vous mesurez en MG, cochez cette option pour rester en Series Layout (un volet par vue — W/L, zoom et mesures indépendants par vue). I-View affiche les mesures même en mosaïque et n'est donc pas concerné.",
  "흉벽 판정": "Détection de la paroi thoracique",
  "자동 — 영상에서 조직 경계를 찾아 잘라냄 (권장)": "Automatique — détection du bord des tissus dans l'image et recadrage (recommandé)",
  "고정 비율 — 안쪽에서 정해진 비율만큼 잘라냄": "Proportion fixe — recadrage d'une proportion définie depuis l'intérieur",
  "배경 임계값": "Seuil de fond",
  "프레임 네 모서리에서 잰": "L'",
  "배경 밝기와의 차이": "écart avec la luminosité de fond mesurée aux quatre coins de l'image",
  "가 이 값을 넘으면 조직으로 봅니다. 조직이 잘리면 낮추고, 여백이 남으면 높입니다.": " au-delà de cette valeur est considéré comme du tissu. Diminuez si du tissu est coupé, augmentez s'il reste du vide.",
