  "원본을 그대로": "telle quelle",
  "표시합니다 — 추정 크롭은 조직을 가릴 수 있습니다.": " en l'absence de données fiables — un recadrage estimé risque de masquer du tissu.",
  "고정 비율": "Proportion fixe",
  "자동 판정이 불가능할 때(외부 서버 영상 등) 안쪽에서 잘라낼 폭.": "Largeur à recadrer depuis l'intérieur lorsque la détection automatique est impossible (images de serveurs externes, etc.).",
