  "상단 가로 메뉴(Image Tool·Measurement·Reading Support·Additional) 스킨. 엔진은 T-View 공유 — 아래 설정(아이콘·오버레이·시네·썸네일·판독창 등)이 동일하게 적용됩니다.": "Habillage du menu horizontal supérieur (Image Tool · Measurement · Reading Support · Additional). Moteur partagé avec T-View — les réglages ci-dessous (icônes, surimpressions, ciné, vignettes, fenêtre de compte rendu, etc.) s'appliquent à l'identique.",
