  "이동 대상 환자가 이미 Exam 탭으로 열려 있으면 그 탭으로 전환되고, 아니면 열면서 이동합니다. Worklist·Image Viewer·Reading Viewer는 열린 환자를 서로 따라갑니다(연동). OK(저장) 시 적용.": "Si le patient de destination est déjà ouvert dans un onglet Exam, l'application bascule vers cet onglet ; sinon, elle l'ouvre. Worklist, Image Viewer et Reading Viewer suivent le patient ouvert (liaison). Appliqué après OK (enregistrer).",
