  "포트는 병원마다 자동 배정(상이)됩니다. ⚠ 단일 Orthanc는 DICOM 포트가 하나라, 실제 병원별 포트 리스닝은 병원별 Orthanc 인스턴스 또는 DICOM 라우터 배치가 필요합니다(여기서는 구성·연결 점검).": "Les ports sont attribués automatiquement et diffèrent selon l'établissement. ⚠ Une instance Orthanc unique n'expose qu'un seul port DICOM : une écoute réellement distincte par établissement nécessite une instance Orthanc par établissement ou un routeur DICOM (ici, il s'agit uniquement de configuration et de vérification de connexion).",
  "🩻 검사 배정": "🩻 Affectation des examens",
  "수신 AET가 등록 장비와 매칭되지 않아 병원이 비어있는(미배정) 검사를 이 병원에 귀속합니다. (Client 뷰어는 로그인한 병원의 검사만 표시하므로, 미배정 검사는 배정해야 보입니다.)": "Rattache à cet établissement les examens sans établissement (non affectés), faute de correspondance entre l'AET de réception et un équipement enregistré. (Le visualiseur client n'affiche que les examens de l'établissement connecté : les examens non affectés doivent donc être attribués.)",
