  "으로 바뀝니다. 부위·출처·Projection·설명은 유지되고, 위 두 체크박스는 기존 값을 불러왔습니다.": ". La région, la source, la projection et la description sont conservées ; les deux cases ci-dessus reprennent les valeurs existantes.",
  "저장되는 것: 이 모니터 · Series/Image 레이아웃 · 칸별 시리즈 · 칸별 과거검사 기간. 3D 창과 다른 모니터 창의 구성은 저장되지 않습니다(같은 이름으로 각 창에서 저장하면 합쳐집니다).": "Éléments enregistrés : cet écran · la disposition Series/Image · la série de chaque case · la période d'examen antérieur de chaque case. La configuration de la fenêtre 3D et des autres écrans n'est pas enregistrée (enregistrer sous le même nom depuis chaque fenêtre les fusionne).",
