  "협진을 쓸 수 없는 계정입니다 — 로그아웃 후 다시 로그인하면 등록됩니다": "Ce compte ne peut pas utiliser la co-lecture — déconnectez-vous puis reconnectez-vous pour l'activer",
  "협진 연결 수가 한도를 넘었습니다 — 사용하지 않는 뷰어 창을 닫으세요": "Le nombre de connexions de co-lecture dépasse la limite — fermez les fenêtres de visualisation inutilisées",
  "다른 창이 다운로드를 맡고 있습니다.": "Le téléchargement est pris en charge par une autre fenêtre.",
  "저장 상한에 도달했습니다 — 자동 삭제가 꺼져 있어 더 받지 않습니다.": "Limite de stockage atteinte — la suppression automatique étant désactivée, plus rien n'est téléchargé.",
  "열려 있는 검사만으로 저장 상한을 넘었습니다 — 설정 > 환경 > 영상 취득에서 [지금 비우기] 를 누르거나 저장 상한을 올려야 이어받습니다.": "Les seuls examens ouverts dépassent la limite de stockage — appuyez sur [Vider maintenant] dans Paramètres > Environnement > Acquisition des images, ou augmentez la limite, pour reprendre le téléchargement.",
  "저장 상한에 도달했습니다 — 보고 있는 검사는 지우지 않으므로, 뷰어 창을 닫거나 상한을 늘리면 이어받습니다.": "Limite de stockage atteinte — les examens consultés n'étant pas supprimés, fermez des fenêtres de visualisation ou augmentez la limite pour reprendre le téléchargement.",
  "뷰어 창이 별도 포트(VITE_VIEWER_BASE)로 뜨는 배치입니다 — 창끼리 저장소를 공유할 수 없어 사용할 수 없습니다.": "Les fenêtres de visualisation s'ouvrent sur un port distinct (VITE_VIEWER_BASE) — elles ne peuvent pas partager le stockage, la fonction est donc indisponible.",
  "보안 컨텍스트(HTTPS 또는 localhost)가 아닙니다 — 브라우저가 OPFS 를 막습니다.": "Le contexte n'est pas sécurisé (HTTPS ou localhost) — le navigateur bloque OPFS.",
  "이 브라우저는 OPFS(navigator.storage.getDirectory)를 지원하지 않습니다.": "Ce navigateur ne prend pas en charge OPFS (navigator.storage.getDirectory).",
  "이 브라우저는 IndexedDB 를 지원하지 않습니다(저장 인덱스에 필요).": "Ce navigateur ne prend pas en charge IndexedDB (nécessaire à l'index de stockage).",
  "이 브라우저는 Window Management API(모니터 감지)를 지원하지 않습니다 — 최신 Chrome/Edge 를 사용하세요.": "Ce navigateur ne prend pas en charge la Window Management API (détection des écrans) — utilisez une version récente de Chrome ou Edge.",
