  "채택 실패": "Échec de l'adoption",
  "초대 시 자동으로 줄 기본 권한": "Autorisations par défaut à l'invitation",
  "여기서 정한 것은 기본값입니다. 협진 중에는 협진 페이지에서 참가자마다 켜고 끌 수 있습니다.": "Ce sont des valeurs par défaut. Pendant la session, vous pouvez les activer par participant dans le panneau de co-lecture.",
  "판독 수정·영상 삭제는 협진으로 절대 위임되지 않습니다 — 목록에 없는 이유입니다.": "La modification du compte rendu et la suppression d'images ne sont jamais déléguées — d'où leur absence.",
  "화면 조작 · 발표자": "Contrôle de l'écran · Présentateur",
  "참가 시 발표자 화면 따라가기 (내가 화면을 만지면 자유 보기로 전환)": "Suivre le présentateur à l'entrée (toucher la vue passe en vue libre)",
  "참가자의 권한 요청을 자동 승인": "Approuver automatiquement les demandes d'autorisation",
  "화면 조작(줌·팬·W/L)은 발표자 1명만 전원에게 송출합니다. 나머지 참가자는 각자 자유롭게 보며, 주석·커서는 항상 전원에게 공유됩니다.": "Seul le présentateur diffuse le contrôle de l'écran (zoom/panoramique/W-L). Les autres naviguent librement ; annotations et curseurs sont toujours partagés.",
  "참여자 표시": "Affichage des participants",
  "마우스 커서 옆에 참여자 아이디 표시": "Afficher l'identifiant du participant à côté du curseur",
  "참여자별 색으로 커서·툴·글자 구분": "Distinguer curseur, outils et texte par couleur de participant",
  "화상·음성 네트워크 (STUN/TURN)": "Réseau vidéo/audio (STUN/TURN)",
  "병원 내부망은 비워 두면 됩니다. 인터넷을 건너는 협진에만 STUN/TURN 을 넣으세요 (JSON 배열).": "Laissez vide sur le réseau interne. Ajoutez STUN/TURN uniquement pour la co-lecture via internet (tableau JSON).",
  "계측·주석 그리기 (세션 한정 — 판독에는 Master 채택 시에만 저장)": "Tracer mesures et annotations (session uniquement — enregistrées seulement si le Master les adopte)",
  "텍스트·글쓰기 (세션 한정)": "Texte et écriture (session uniquement)",
  "검사 탭 전환·과거 검사 열기": "Changer d'onglet d'examen / ouvrir des examens antérieurs",
  "적용 순서(고정)": "Ordre d'application (fixe)",
  ": ① 행잉(HP — 선택 시만) → ② Mammo(2D-MG — 선택 시만) → ③ 이 Common 표 → ④ 각 뷰어별 표 → ⑤ 자동 규칙(1×1 등).": " : ① Protocole (HP — seulement si sélectionné) → ② Mammo (2D-MG — seulement si activé) → ③ cette table Common → ④ table par visionneuse → ⑤ règles automatiques (1×1, etc.).",
  "이 표에 해당 모달리티 행이 있으면 세 뷰어(SaintView/I-View/T-View) 모두 이 값을 씁니다. 행이 없으면 그 뷰어의 개별 표를 봅니다.": "Si cette table contient une ligne pour la modalité, les trois visionneuses (SaintView/I-View/T-View) l'utilisent. Sinon, la table propre à la visionneuse est consultée.",
  "규정이 켜져 있을 때만 그 규정을 따릅니다(이 표에 MG 행이 없는 이유).": "ne s'applique que lorsque cette règle est activée (d'où l'absence de ligne MG dans cette table).",
  "행은 그 표에 행이 없는 나머지 모달리티에 적용됩니다 —": "s'applique aux autres modalités absentes de cette table —",
  "적용 순서(고정): Common 표에 그 모달리티 행이 있으면 Common 이 우선하고, 없을 때 이 표가 적용됩니다.": "Ordre (fixe) : si la table Common contient une ligne pour la modalité, Common prime ; cette table ne s'applique qu'à défaut.",
  ")는 아래": ") suit la règle",
  "별도 창으로 크게 보기 (다른 모니터로 옮길 수 있습니다)": "Ouvrir dans une fenêtre séparée (déplaçable vers un autre écran)",
  "팝업이 차단되었습니다 — 이 사이트의 팝업을 허용해 주세요": "Fenêtre pop-up bloquée — autorisez les pop-ups pour ce site",
  "협진 패널 숨기기 (오른쪽으로 접기)": "Masquer le panneau de co-lecture (replier à droite)",
  "협진 패널 펼치기": "Afficher le panneau de co-lecture",
  "드래그하면 폭이 바뀝니다 (더블클릭 = 기본 폭)": "Faites glisser pour redimensionner (double-clic = largeur par défaut)",
  "좌우 비율 무시": "Ignorer le ratio G/D",
  "조직 탐지와 무관하게 항상 같은 고정 비율로 가운데 여백 제거 (기본 켬)": "Toujours rogner l'espace central au même ratio fixe, indépendamment de la détection du tissu (activé par défaut)",
  "자동 탐지가 영상마다 실패·지연하면 배치가 들쭉날쭉해집니다 — 켜 두면 항상 같은 모양으로 나옵니다. 해제하면 아래 흉벽 판정(자동 탐지) 규칙을 씁니다.": "Si la détection automatique échoue ou tarde sur certaines images, la disposition devient irrégulière — laissez activé pour un rendu constant. Décochez pour utiliser les règles de détection de la paroi thoracique ci-dessous.",
  "드래그 = 컬럼 위치 이동 · 오른쪽 가장자리 드래그 = 폭 조절": "Glisser = déplacer la colonne · bord droit = régler la largeur",
  "나이": "Âge",
